// 03 Resolve + Precheck — 02 已經讀到選中的那一列，這裡展開 scopes + 做 precheck
// 下游節點只看 projectName / scopes / warnings；原始 Sheet row 藏在 _rawRow 只給 04 Prepare Write Args 用

const row = $json;
const scopesOverride = ($('01 Form Trigger (pick project)').first().json.scopesOverride || '').trim();

if (!row.project_name) throw new Error('Sheet row 缺 project_name');
if (!row.target_url)   throw new Error('Sheet row 缺 target_url');

// Preset 展開
const ALL    = ['precheck','static','unit','api-test','db-test','links','ssl','trivy','lighthouse','e2e','nuclei','security','stress','monkey'];
const REMOTE = ['precheck','ssl','security','nuclei','stress','lighthouse','links','monkey'];
const LOCAL  = ['static','unit','trivy','db-test'];
function parseScopes(raw) {
  if (Array.isArray(raw)) return raw;
  if (!raw) return [];
  return String(raw).split(',').map(s => s.trim()).filter(Boolean);
}
function expandPresets(list) {
  const out = new Set();
  for (const s of list) {
    if (s === 'ALL' || s === 'all') ALL.forEach(x => out.add(x));
    else if (s === 'REMOTE_ONLY' || s === 'remote-only') REMOTE.forEach(x => out.add(x));
    else if (s === 'LOCAL_ONLY' || s === 'local-only') LOCAL.forEach(x => out.add(x));
    else out.add(s);
  }
  return [...out];
}
const scopes = expandPresets(parseScopes(scopesOverride || row.scopes));

// Precheck warnings
const warnings = [];
const scopeSet = new Set(scopes);
if (!row.local_path) {
  warnings.push('local_path 未設 → skip static/unit/trivy/db-test');
  ['static','unit','trivy','db-test'].forEach(s => scopeSet.delete(s));
}
if (!row.target_url.startsWith('https://') && scopeSet.has('ssl')) {
  warnings.push('target_url 非 https → skip ssl');
  scopeSet.delete('ssl');
}
const finalScopes = [...scopeSet];

return [{ json: {
  projectName: row.project_name,
  scopes: finalScopes,
  scopesCsv: finalScopes.join(','),
  warnings,
  _rawRow: row
}}];

// 06 Prepare Write Args — 從 _rawRow 生 base64 env + 把 _rawRow 砍掉
const r = $json._rawRow || {};
const envLines = [];
const add = (k, v) => { if (v) envLines.push(`${k}=${v}`); };
add('ADMIN_USERNAME', r.admin_username);
add('ADMIN_PASSWORD', r.admin_password);
add('E2E_USERNAME', r.e2e_username);
add('E2E_PASSWORD', r.e2e_password);
for (let i = 1; i <= 5; i++) {
  add(`USER${i}_USERNAME`, r[`user${i}_username`]);
  add(`USER${i}_PASSWORD`, r[`user${i}_password`]);
  add(`USER${i}_LABEL`,    r[`user${i}_label`]);
}
const envB64 = Buffer.from(envLines.join('\n') + (envLines.length ? '\n' : ''), 'utf-8').toString('base64');
return {
  projectName: $json.projectName,
  scopes: $json.scopes,
  scopesCsv: $json.scopesCsv,
  warnings: $json.warnings,
  // 只給 07 Write 用
  _writeArgs: {
    localPath: r.local_path || '',
    targetUrl: r.target_url || '',
    phpVersion: r.php_version || '8.1',
    envB64
  }
};

// 06 Extract registry path + 精簡 JSON（徹底清掉 _writeArgs / _rawRow）
const stdout = $json.stdout || '';
const lines = stdout.trim().split('\n').filter(Boolean);
const registryPath = lines[lines.length - 1] || '';
if (!registryPath) throw new Error('write-project-config.sh 未回傳 registry path');

const upstream = $('04 Prepare Write Args').itemMatching($itemIndex).json;
return {
  projectName: upstream.projectName,
  scopes: upstream.scopes,
  scopesCsv: upstream.scopesCsv,
  warnings: upstream.warnings,
  registryPath
};

// 27 Parse Results — 最後端點
const pname = $('06 Extract Path').first().json.projectName;
const warnings = $('06 Extract Path').first().json.warnings || [];
let parsed = {};
try {
  parsed = JSON.parse($json.stdout);
} catch (e) {
  return {
    projectName: pname,
    parseError: e.message,
    rawStdout: ($json.stdout || '').slice(0, 500),
    warnings
  };
}
const merged = [...new Set([...(parsed.warnings || []), ...warnings])];
return {
  projectName: pname,
  overallScore: parsed.lighthouse?.avg?.performance ?? null,
  reportDir: parsed.reports_dir,
  reportMd: parsed.report_md,
  warnings: merged,
  // 展開摘要欄位，Schema 面板直接看
  ssl: parsed.ssl,
  static: parsed.static,
  security: parsed.security,
  stress: parsed.stress,
  unit: parsed.unit,
  e2e: parsed.e2e,
  nuclei: parsed.nuclei,
  lighthouse: parsed.lighthouse?.avg,
  monkey: parsed.monkey,
  trivy: parsed.trivy ? { total: parsed.trivy.total, critical: parsed.trivy.critical, high: parsed.trivy.high } : null,
  links: parsed.links ? { total: parsed.links.total, errors: parsed.links.errors } : null
};
